from __future__ import annotations

def escape_time(c: complex, max_iter: int = 1000, radius: float = 2.0) -> int | None:
    z = 0.0 + 0.0j
    for n in range(max_iter):
        z = z * z + c
        if abs(z) > radius:
            return n
    return None

def in_mandelbrot(c: complex, max_iter: int = 2000) -> bool:
    return escape_time(c, max_iter=max_iter) is None

if __name__ == '__main__':
    for c in [0.0, -1.0, -2.0, 0.25, 0.3, 1.0, -0.75 + 0.1j]:
        t = escape_time(c)
        print(c, 'bounded' if t is None else f'escapes at {t}')

from math import gcd

def additive_order(p: int, q: int) -> int:
    p %= q
    k, acc = 1, p % q
    while acc != 0:
        acc = (acc + p) % q
        k += 1
    return k

if __name__ == '__main__':
    for q in range(2, 21):
        for p in range(1, q):
            if gcd(p, q) == 1:
                assert additive_order(p, q) == q
    print('period = denominator verified for all reduced p/q, q <= 20')

def fib(n: int) -> int:
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def cassini(n: int) -> int:
    return fib(n + 1) ** 2 - fib(n) * fib(n + 2)

if __name__ == '__main__':
    for n in range(1, 12):
        a, b = fib(n), fib(n + 1)
        c, d = fib(n + 1), fib(n + 2)
        assert cassini(n) == (-1) ** n
        assert abs(b * c - a * d) == 1
        print(f'{a}/{b} ~ {c}/{d}  Cassini={cassini(n)}  neighbour=True')

