def lcm(a: int, b: int) -> int:
    return a * b // gcd(a, b)

def factor(n: int) -> dict[int, int]:
    f, d = {}, 2
    while d * d <= n:
        while n % d == 0:
            f[d] = f.get(d, 0) + 1
            n //= d
        d += 1
    if n > 1:
        f[n] = f.get(n, 0) + 1
    return f

if __name__ == '__main__':
    for n in range(2, 101):
        parts = [p ** a for p, a in factor(n).items()]
        if len(parts) < 2:
            continue
        q1 = parts[0]; q2 = n // q1
        for a in range(1, min(n, 30)):
            assert additive_order(a % n, n) == lcm(additive_order(a % q1, q1), additive_order(a % q2, q2))
    print('CRT product law verified for composite periods n <= 100')

