from math import gcd

def additive_order(p: int, q: int) -> int:
    p %= q
    acc, k = p % q, 1
    while acc != 0:
        acc = (acc + p) % q
        k += 1
    return k

def prime_factorization(n: int) -> dict[int, int]:
    f: dict[int, int] = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            f[d] = f.get(d, 0) + 1
            n //= d
        d += 1
    if n > 1:
        f[n] = f.get(n, 0) + 1
    return f

def composite_order(a: int, n: int) -> int:
    result = 1
    for p, e in prime_factorization(n).items():
        q = p ** e
        o = additive_order(a % q, q)
        result = result * o // gcd(result, o)
    return result
